import { ART_WIDTH, ART_HEIGHT, DAY_ART, NIGHT_ART } from './world-art.js?v=building-cards-1';
import { setText, setAttributeText, localize } from './i18n.js';
import { PALETTE,nextGeneration,seedPattern } from './pixel-core.js';
import { BOOKS } from './books.js';
import { createMusicRoom } from './music-room.js';
export function createRooms({locations,audio,toast,onClose}){
const dialog=document.getElementById('room'),content=document.getElementById('room-content');
let current=null,cleanup=()=>{},resizer=()=>{},noteDraft={title:'',body:''},noteSaved=false;
try{const n=JSON.parse(localStorage.getItem('cabbageland:pixel:notebook'));if(n&&typeof n.title==='string'&&typeof n.body==='string'){noteDraft=n;noteSaved=true;}}catch{}
const musicRoom=createMusicRoom({content,audio,toast});
const W=24,H=16,lab={cells:seedPattern('glider',W,H),generation:0,timer:null,playing:false,pattern:'glider'};
const drawing={pixels:Array(32*24).fill(-1),history:[],color:1,eraser:false,down:false,last:null};
const articles=[
{title:'article.1.title',body:['article.1.body1','article.1.body2']},
{title:'article.2.title',body:['article.2.body1','article.2.body2']},
{title:'article.3.title',body:['article.3.body1','article.3.body2']}
];let article=0;
function pauseLab(){if(lab.timer)clearInterval(lab.timer);lab.timer=null;lab.playing=false;const b=content.querySelector('#run-life');if(b){setText(b,'lab.run');b.setAttribute('aria-pressed','false');}}
function pause(){musicRoom.pause();pauseLab();}
function close(){dialog.close();}
document.getElementById('leave-room').onclick=close;document.getElementById('close-room').onclick=close;
dialog.addEventListener('close',()=>{cleanup();pause();current=null;onClose();});
dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();});
function resizePortrait(){
 if(!current)return;
 const p=locations[current],el=document.getElementById('portrait-image'),frame=el.parentElement;
 const width=frame.clientWidth,height=frame.clientHeight;
 if(!width||!height)return;
 if(p.cardArt){
  const aspect=p.cardAspect||4/5;
  const cardWidth=Math.min(width,height*aspect),cardHeight=cardWidth/aspect;
  el.style.width=`${cardWidth}px`;
  el.style.height=`${cardHeight}px`;
  el.style.backgroundImage=`url("${p.cardArt}")`;
  el.style.backgroundSize='100% 100%';
  el.style.backgroundPosition='center';
  setAttributeText(el,'aria-label','room.portrait',{name:p.name});
  return;
 }
 el.style.removeProperty('background-image');
 // Keep the entire selected building inside its frame, including its sign.
 // The crop uses the same artwork coordinates in daylight and at night.
 const [x,y,w,h]=p.portraitRect||p.rect,padding=8;
 const left=Math.max(0,x-padding),top=Math.max(0,y-padding);
 const right=Math.min(ART_WIDTH,x+w+padding),bottom=Math.min(ART_HEIGHT,y+h+padding);
 const cropWidth=right-left,cropHeight=bottom-top;
 const scale=Math.min(width/cropWidth,height/cropHeight);
 el.style.width=`${cropWidth*scale}px`;
 el.style.height=`${cropHeight*scale}px`;
 el.style.backgroundSize=`${ART_WIDTH*scale}px ${ART_HEIGHT*scale}px`;
 el.style.backgroundPosition=`${-left*scale}px ${-top*scale}px`;
 setAttributeText(el,'aria-label','room.portrait',{name:p.name});
}
const portraitObserver=new ResizeObserver(resizePortrait);
portraitObserver.observe(document.querySelector('.portrait-art'));

function open(key){if(!locations[key])return;cleanup();pause();current=key;const p=locations[key];document.getElementById('room-title').textContent=p.name;document.getElementById('room-subtitle').textContent=p.sub;setText(document.getElementById('room-number'),'room.number',{number:p.number});document.getElementById('room-category').textContent=p.tag;dialog.dataset.room=key;cleanup=()=>{};resizer=()=>{};if(key==='read')reading();if(key==='music')cleanup=musicRoom.mount();if(key==='nerd')nerdRoom();if(key==='art')artRoom();if(key==='pets'||key==='great')placeIntro(key);if(!dialog.open)dialog.showModal();content.scrollTop=0;requestAnimationFrame(()=>{resizePortrait();resizer();});}
// Replace these localized placeholders when Tracy supplies introductions.
function placeIntro(key){content.innerHTML=`<div class="place-intro"><span class="eyebrow" data-i18n="${key}.eyebrow"></span><h2 data-i18n="${key}.title"></h2><p class="intro" data-i18n="${key}.intro"></p><div class="intro-note"><span class="intro-note-symbol" aria-hidden="true">✳</span><div><h3 data-i18n="${key}.soon"></h3><p data-i18n="${key}.placeholder"></p></div></div></div>`;localize(content);}
function tabs(ids){const buttons=content.querySelectorAll('[data-tab]');buttons.forEach(b=>b.onclick=()=>{buttons.forEach(x=>{const on=x===b;x.setAttribute('aria-selected',String(on));x.tabIndex=on?0:-1;});for(const id of ids)document.getElementById(id).hidden=id!==b.dataset.tab;resizer();});buttons.forEach((b,i)=>b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[n].click();buttons[n].focus();}));}
function reading(){content.innerHTML=`<span class="eyebrow" data-i18n="reading.eyebrow">THE LITTLE READING POST</span><h2 data-i18n="reading.title">读一点，也写一点。</h2><div class="tabs" role="tablist" aria-label="书报亭" data-i18n-aria-label="reading.tabs"><button role="tab" id="reading-tab" aria-controls="reading-panel" aria-selected="true" data-tab="reading-panel" data-i18n="reading.readTab">阅读角</button><button role="tab" id="mailbox-tab" aria-controls="mailbox-panel" aria-selected="false" tabindex="-1" data-tab="mailbox-panel" data-i18n="reading.mailTab">Mailbox</button><button role="tab" id="note-tab" aria-controls="note-panel" aria-selected="false" tabindex="-1" data-tab="note-panel" data-i18n="reading.noteTab">我的手记</button></div><div id="reading-panel" class="tab-panel" role="tabpanel" aria-labelledby="reading-tab"><p class="intro" data-i18n="books.intro"></p><div class="book-collection">${BOOKS.map((book,i)=>`<a class="book-entry" href="${book.url}" target="_blank" rel="noopener noreferrer"><span class="book-number">0${i+1}</span><div><span class="book-format" data-i18n="${book.format}"></span><h3>${book.title}</h3><p data-i18n="${book.description}"></p><span class="book-open" data-i18n="books.open"></span></div></a>`).join('')}</div><p class="rule-note" data-i18n="books.newTab"></p></div><div id="mailbox-panel" class="tab-panel" role="tabpanel" aria-labelledby="mailbox-tab" hidden><article class="paper-article"><span class="article-number" data-i18n="reading.letters">LETTERS FROM CABBAGELAND</span><h3 id="article-title"></h3><div id="article-body"></div><footer><span data-i18n="reading.original">岛上短笺 · 原创</span><div class="pager"><button id="previous-page" aria-label="上一篇" data-i18n-aria-label="reading.previous">‹</button><span id="page-number"></span><button id="next-page" aria-label="下一篇" data-i18n-aria-label="reading.next">›</button></div></footer></article><p class="rule-note" data-i18n="reading.noteHint">在「我的手记」里，留下你自己的文字。</p></div><div id="note-panel" class="tab-panel" role="tabpanel" aria-labelledby="note-tab" hidden><label class="notebook-label" for="note-title" data-i18n="note.title">标题</label><input id="note-title" class="note-title" maxlength="100" placeholder="给这一页取个名字" data-i18n-placeholder="note.titlePlaceholder"><label class="notebook-label" for="note-body" data-i18n="note.body">今天想留下什么？</label><textarea id="note-body" class="note-body" placeholder="一个念头、一个问题，或一段还没写完的故事。" data-i18n-placeholder="note.bodyPlaceholder"></textarea><div class="field-meta"><span id="note-status"></span><span id="note-count"></span></div><div class="action-row"><button id="save-note" class="pixel-button primary" data-i18n="note.save">▤ 保存手记</button></div><p class="rule-note" data-i18n="note.local">保存后保留在当前浏览器，换设备不会同步。</p></div>`;localize(content);
function renderArticle(){const a=articles[article];setText(document.getElementById('article-title'),a.title);const body=document.getElementById('article-body');body.replaceChildren(...a.body.map(t=>{const p=document.createElement('p');setText(p,t);return p;}));document.getElementById('page-number').textContent=`${article+1} / ${articles.length}`;}
renderArticle();document.getElementById('previous-page').onclick=()=>{article=(article+articles.length-1)%articles.length;renderArticle();};document.getElementById('next-page').onclick=()=>{article=(article+1)%articles.length;renderArticle();};
const title=document.getElementById('note-title'),body=document.getElementById('note-body'),status=document.getElementById('note-status');title.value=noteDraft.title;body.value=noteDraft.body;setText(status,noteSaved?'note.loaded':'note.empty');function count(){setText(document.getElementById('note-count'),'note.count',{count:Array.from(body.value).length});}count();for(const e of [title,body])e.addEventListener('input',()=>{noteDraft={title:title.value,body:body.value};setText(status,'note.unsaved');count();});document.getElementById('save-note').onclick=()=>{try{localStorage.setItem('cabbageland:pixel:notebook',JSON.stringify(noteDraft));noteSaved=true;setText(status,'note.saved');toast('note.savedToast');}catch{setText(status,'note.blocked');toast('note.saveError');}};tabs(['reading-panel','mailbox-panel','note-panel']);}
function nerdRoom(){content.innerHTML=`<span class="eyebrow" data-i18n="lab.eyebrow">A SMALL FIELD FOR BIG QUESTIONS</span><h2 data-i18n="lab.title">简单规则，会长出什么？</h2><p class="intro" data-i18n="lab.intro">这块实验田运行「生命游戏」。点击格子播种，再让它自己演化。</p><div class="experiment"><canvas id="life-canvas" class="experiment-screen" width="720" height="480" tabindex="0" aria-label="生命游戏实验田，24列16行。点击格子添加或移除细胞，也可用方向键移动，空格切换。" data-i18n-aria-label="lab.canvas"></canvas><div class="experiment-stats"><span><span data-i18n="lab.generation">GEN</span> <b id="generation">0</b></span><span><span data-i18n="lab.alive">ALIVE</span> <b id="alive">0</b></span><span>24 × 16</span></div></div><div class="action-row"><button class="pixel-button primary" id="run-life" aria-pressed="false" data-i18n="lab.run">▶ 运行</button><button class="pixel-button" id="step-life" data-i18n="lab.step">单步</button><select id="life-pattern" class="experiment-select" aria-label="实验种子" data-i18n-aria-label="lab.pattern"><option value="glider" data-i18n="lab.glider">滑翔机</option><option value="oscillator" data-i18n="lab.oscillator">振荡器</option><option value="random" data-i18n="lab.random">随机种子</option></select><button class="pixel-button" id="reset-life" data-i18n="common.reset">重置</button><button class="pixel-button" id="clear-life" data-i18n="common.clear">清空</button></div><p class="rule-note" data-i18n="lab.rules">活细胞有 2–3 个邻居时存活；空格有 3 个邻居时生长。其余细胞消失，边界之外为空地。</p><div class="code-note">next = neighbors === 3 || (alive && neighbors === 2)</div>`;localize(content);
const canvas=document.getElementById('life-canvas'),ctx=canvas.getContext('2d');let painting=false,value=1,selection=[Math.floor(W/2),Math.floor(H/2)],keyboard=false;
document.getElementById('life-pattern').value=lab.pattern;
function render(){ctx.fillStyle='#173424';ctx.fillRect(0,0,720,480);for(let yy=0;yy<H;yy++)for(let xx=0;xx<W;xx++){ctx.fillStyle=lab.cells[yy*W+xx]?'#b9d763':((xx+yy)%2?'#27482f':'#294c31');ctx.fillRect(xx*30+2,yy*30+2,26,26);if(lab.cells[yy*W+xx]){ctx.fillStyle='#dce998';ctx.fillRect(xx*30+5,yy*30+5,20,5);}}if(keyboard){ctx.strokeStyle='#fbe4a0';ctx.lineWidth=3;ctx.strokeRect(selection[0]*30+1.5,selection[1]*30+1.5,27,27);}document.getElementById('generation').textContent=lab.generation;document.getElementById('alive').textContent=lab.cells.reduce((a,b)=>a+b,0);}
function step(){lab.cells=nextGeneration(lab.cells,W,H);lab.generation++;render();}
function point(e){const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(W-1,Math.floor((e.clientX-r.left)/r.width*W))),Math.max(0,Math.min(H-1,Math.floor((e.clientY-r.top)/r.height*H)))];}
canvas.onpointerdown=e=>{e.preventDefault();pauseLab();keyboard=false;painting=true;canvas.setPointerCapture(e.pointerId);const [x,y]=point(e);value=lab.cells[y*W+x]?0:1;lab.cells[y*W+x]=value;render();};canvas.onpointermove=e=>{if(!painting)return;const [x,y]=point(e);lab.cells[y*W+x]=value;render();};canvas.onpointerup=canvas.onpointercancel=()=>painting=false;
canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key))return;e.preventDefault();pauseLab();keyboard=true;selection[0]=Math.max(0,Math.min(W-1,selection[0]+(e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0)));selection[1]=Math.max(0,Math.min(H-1,selection[1]+(e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0)));if(e.key===' ')lab.cells[selection[1]*W+selection[0]]^=1;render();};
document.getElementById('run-life').onclick=()=>{if(lab.playing){pauseLab();return;}lab.playing=true;setText(document.getElementById('run-life'),'common.pause');document.getElementById('run-life').setAttribute('aria-pressed','true');lab.timer=setInterval(step,230);};document.getElementById('step-life').onclick=()=>{pauseLab();step();};const reset=()=>{pauseLab();lab.cells=seedPattern(lab.pattern,W,H);lab.generation=0;render();};document.getElementById('life-pattern').onchange=e=>{lab.pattern=e.target.value;reset();};document.getElementById('reset-life').onclick=reset;document.getElementById('clear-life').onclick=()=>{pauseLab();lab.cells=new Uint8Array(W*H);lab.generation=0;render();};render();cleanup=pauseLab;}
function artRoom(){content.innerHTML=`<span class="eyebrow" data-i18n="art.eyebrow">MY WORLD, IN A FEW PIXELS</span><h2 data-i18n="art.title">把想象留在画里。</h2><div class="tabs" role="tablist" aria-label="画廊" data-i18n-aria-label="art.tabs"><button role="tab" id="gallery-tab" aria-controls="gallery-panel" aria-selected="true" data-tab="gallery-panel" data-i18n="art.galleryTab">作品</button><button role="tab" id="drawing-tab" aria-controls="drawing-panel" aria-selected="false" tabindex="-1" data-tab="drawing-panel" data-i18n="art.drawingTab">像素画板</button></div><div id="gallery-panel" class="tab-panel" role="tabpanel" aria-labelledby="gallery-tab"><div class="gallery-collection"><figure class="gallery-piece"><div class="gallery-frame"><a href="${DAY_ART}" target="_blank" rel="noopener" data-i18n-aria-label="art.openOriginal"><img src="${DAY_ART}" data-i18n-alt="art.originalAlt" width="${ART_WIDTH}" height="${ART_HEIGHT}" loading="eager"></a></div><figcaption class="art-label"><b data-i18n="art.dayTitle">Cabbageland / Daylight</b><span data-i18n="art.origin">Where this world began</span></figcaption></figure><figure class="gallery-piece"><div class="gallery-frame"><a href="${NIGHT_ART}" target="_blank" rel="noopener" data-i18n-aria-label="art.openNight"><img src="${NIGHT_ART}" data-i18n-alt="art.nightAlt" width="${ART_WIDTH}" height="${ART_HEIGHT}" loading="lazy"></a></div><figcaption class="art-label"><b data-i18n="art.nightTitle">Cabbageland / After dark</b><span data-i18n="art.nightCaption">Moonlight, streams, and glowing windows</span></figcaption></figure></div><p><span data-i18n="art.description1">一颗卷心菜，一片小天地。</span><br><span data-i18n="art.description2">点开画作可以查看完整原图，也可以去画板留下新的想象。</span></p></div><div id="drawing-panel" class="tab-panel" role="tabpanel" aria-labelledby="drawing-tab" hidden><p class="intro" data-i18n="art.drawIntro">选一种颜色，在小画布上画点什么。</p><div class="drawing-board"><canvas id="drawing-canvas" width="640" height="480" tabindex="0" aria-label="32列24行像素画板。拖动绘画；方向键移动光标，空格绘画。" data-i18n-aria-label="art.canvas"></canvas></div><div class="palette" aria-label="画笔颜色" data-i18n-aria-label="art.palette">${PALETTE.map((c,i)=>`<button class="swatch" data-color="${i}" style="--color:${c}" data-i18n-aria-label="art.color" data-i18n-vars='${JSON.stringify({color:c})}'  aria-pressed="${drawing.color===i&&!drawing.eraser}"></button>`).join('')}<div class="draw-tools"><button id="eraser" aria-pressed="${drawing.eraser}" data-i18n="art.eraser">橡皮</button><button id="undo-drawing" aria-label="撤销上一次笔画" data-i18n-aria-label="art.undoLabel" data-i18n="art.undo">↶ 撤销</button></div></div><div class="action-row"><button id="export-drawing" class="pixel-button primary" data-i18n="art.export">↓ 导出 PNG</button><button id="clear-drawing" class="pixel-button" data-i18n="art.clear">清空画板</button></div><p class="rule-note" data-i18n="art.local">32 × 24 像素 · 画作仅在当前页面保留，完成后记得导出。</p></div>`;localize(content);
const canvas=document.getElementById('drawing-canvas'),ctx=canvas.getContext('2d');let keyboard=false,cursor=[15,11];
function render(){ctx.fillStyle='#faf1d3';ctx.fillRect(0,0,640,480);for(let y=0;y<24;y++)for(let x=0;x<32;x++){const c=drawing.pixels[y*32+x];if(c>=0){ctx.fillStyle=PALETTE[c];ctx.fillRect(x*20,y*20,20,20);}}ctx.strokeStyle='#29432315';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<=32;x++){ctx.moveTo(x*20,0);ctx.lineTo(x*20,480);}for(let y=0;y<=24;y++){ctx.moveTo(0,y*20);ctx.lineTo(640,y*20);}ctx.stroke();if(keyboard){ctx.strokeStyle='#c66a34';ctx.lineWidth=2;ctx.strokeRect(cursor[0]*20+1,cursor[1]*20+1,18,18);}document.getElementById('undo-drawing').disabled=drawing.history.length===0;}
function snapshot(){drawing.history.push([...drawing.pixels]);if(drawing.history.length>30)drawing.history.shift();}
function xy(e){const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(31,Math.floor((e.clientX-r.left)/r.width*32))),Math.max(0,Math.min(23,Math.floor((e.clientY-r.top)/r.height*24)))];}
function paint(p){if(drawing.last){let [x0,y0]=drawing.last;const [x1,y1]=p,dx=Math.abs(x1-x0),sx=x0<x1?1:-1,dy=-Math.abs(y1-y0),sy=y0<y1?1:-1;let err=dx+dy;for(;;){drawing.pixels[y0*32+x0]=drawing.eraser?-1:drawing.color;if(x0===x1&&y0===y1)break;const e=2*err;if(e>=dy){err+=dy;x0+=sx;}if(e<=dx){err+=dx;y0+=sy;}}}else drawing.pixels[p[1]*32+p[0]]=drawing.eraser?-1:drawing.color;drawing.last=p;render();}
canvas.onpointerdown=e=>{e.preventDefault();keyboard=false;snapshot();drawing.down=true;drawing.last=null;canvas.setPointerCapture(e.pointerId);paint(xy(e));};canvas.onpointermove=e=>{if(drawing.down)paint(xy(e));};canvas.onpointerup=canvas.onpointercancel=()=>{drawing.down=false;drawing.last=null;};
canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key))return;e.preventDefault();keyboard=true;cursor[0]=Math.max(0,Math.min(31,cursor[0]+(e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0)));cursor[1]=Math.max(0,Math.min(23,cursor[1]+(e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0)));if(e.key===' '){snapshot();drawing.last=null;paint(cursor);drawing.last=null;}render();};
function updatePalette(){content.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.color===drawing.color&&!drawing.eraser)));document.getElementById('eraser').setAttribute('aria-pressed',String(drawing.eraser));}
content.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{drawing.color=+b.dataset.color;drawing.eraser=false;updatePalette();});document.getElementById('eraser').onclick=()=>{drawing.eraser=!drawing.eraser;updatePalette();};document.getElementById('undo-drawing').onclick=()=>{if(drawing.history.length){drawing.pixels=drawing.history.pop();render();}};document.getElementById('clear-drawing').onclick=()=>{snapshot();drawing.pixels.fill(-1);render();toast('art.cleared');};
document.getElementById('export-drawing').onclick=()=>{const out=document.createElement('canvas');out.width=640;out.height=480;const c=out.getContext('2d');c.fillStyle='#faf1d3';c.fillRect(0,0,640,480);for(let y=0;y<24;y++)for(let x=0;x<32;x++){const v=drawing.pixels[y*32+x];if(v>=0){c.fillStyle=PALETTE[v];c.fillRect(x*20,y*20,20,20);}}out.toBlob(blob=>{if(!blob){toast('art.exportError');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-world-in-XD.png';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('art.download');},'image/png');};
resizer=render;tabs(['gallery-panel','drawing-panel']);render();cleanup=()=>{drawing.down=false;drawing.last=null;};}
function refreshLanguage(){
 if(!current)return;
 const p=locations[current];
 document.getElementById('room-title').textContent=p.name;
 document.getElementById('room-subtitle').textContent=p.sub;
 document.getElementById('room-category').textContent=p.tag;
 resizePortrait();
}
return {open,pause,refreshLanguage,resize(){resizePortrait();resizer();}};
}
